def f(n):
    return n // 10 + 3 * (n % 10)

n = 26**135
for i in range(135):
    n = f(n)
print(f"n_{135} = {n}")

# Now we have n_135. Let's see what happens after many operations.
current_n = n
history = []
for i in range(2025 - 135):
    if current_n in history:
        print(f"Cycle detected at step {i} with n = {current_n}")
        break
    history.append(current_n)
    current_n = f(current_n)
else:
    print(f"No cycle detected. Final n = {current_n}")

